import {PLANTS,initialState,validateState,replacePlant,addEvent,numeric,demoSeries,toCSV} from './core.js';
import {translate} from './i18n.js';
import {icon,plantArt} from './art.js';

const KEY='folium.state.v1',CHECK_KEY='folium.checks.v1';
let state=initialState(),storageFailed=false,chartRange='day',journalFilter='all',photoURLs=[],renderId=0;
try{const stored=localStorage.getItem(KEY);if(stored)state=validateState(JSON.parse(stored));}catch{storageFailed=true;}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const t=k=>translate(state.lang,k);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const locale=()=>({ru:'ru-RU',ro:'ro-RO',en:'en-GB'}[state.lang]);
const date=v=>new Intl.DateTimeFormat(locale(),{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(v));
const events=()=>state.events.filter(e=>e.mode===state.mode);
const route=()=>{const [name,id]=(location.hash.slice(1)||'overview').split('/');return {name:['overview','plants','journal','photos','settings','plant'].includes(name)?name:'overview',id};};
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;storageFailed=false;return true;}catch{toast(t('error'));return false;}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
function plantOptions(selected){return PLANTS.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${t(p.id)}</option>`).join('');}
function modeStrip(){return `<div class="mode-strip"><span class="mode-dot"></span><span class="mode-name">${t(state.mode==='demo'?'demo':'real')}</span><span>${t(state.mode==='demo'?'demoNote':'realNote')}</span><a href="#settings">${t('mode')}</a></div>`;}
function button(text,action,ico='plus',classes='primary',extra=''){return `<button class="btn ${classes}" data-action="${action}" ${extra}>${icon(ico,16)}${text}</button>`;}
function shell(content){const r=route(),active=r.name==='plant'?'plants':r.name;return `<aside class="sidebar"><a href="#overview" class="brand" aria-label="Folium"><span class="brand-icon">${icon('plant',37)}</span><span class="brand-word">folium<small>GROW WITH CARE</small></span></a><nav class="nav" aria-label="${t('garden')}">${[['overview','grid'],['plants','leaf'],['journal','book'],['photos','camera'],['settings','settings']].map(([id,ico])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ico)}<span>${t(id)}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('plant',25)}<strong>${t('subtitle')}</strong>${t('localOnly')}</div><div class="account"><div class="avatar">NV</div><div class="account-name">Nichita Vasiliev<small>CR-232 · Folium</small></div></div></div></aside><main id="main"><header class="topbar"><div class="breadcrumb">${icon('leaf',17)}<span>${t('garden')}</span>${icon('chevron',11)}<b>${t(active)}</b></div><div class="date">${new Intl.DateTimeFormat(locale(),{day:'numeric',month:'long',year:'numeric'}).format(new Date())}</div><div class="lang-picker" aria-label="${t('language')}">${['ro','ru','en'].map(l=>`<button data-action="language" data-lang="${l}" lang="${l}" class="${state.lang===l?'active':''}" aria-pressed="${state.lang===l}">${l.toUpperCase()}</button>`).join('')}</div>${button(t('add'),'log')}</header>${storageFailed?`<p class="error-banner">${t('error')}</p>`:''}${modeStrip()}${content}<footer class="footer"><span>${t('footer')}</span><span>${t('localOnly')} · v0.1</span></footer></main>`;}
function card(p){const ch=state.channels.indexOf(p.id),active=ch>=0,demo=state.mode==='demo'&&active;const latest=events().find(e=>e.plantId===p.id&&e.moisture!=null);let val=demo?demoSeries(p.id).at(-1):latest?.moisture;return `<a class="plant-card" href="#plant/${p.id}" aria-label="${t('profile')}: ${t(p.id)}"><div class="plant-visual ${p.color}"><span class="channel-tag">${active?icon('wifi',10):icon('clock',10)}${active?t('channel')+' 0'+(ch+1):t('reserve')}</span>${plantArt(p.id,'card-'+p.id)}</div><div class="plant-body"><h3 class="plant-name">${t(p.id)}</h3><div class="latin">${p.id==='cactus'?t('notSpecies'):p.latin}</div><div class="plant-metrics"><span>${icon('drop',13)}${t('moisture')}</span><b>${val!=null?esc(val):'—'} <small>${val!=null?t('unit'):''}</small></b></div><div class="plant-status ${!demo?'muted':p.id==='tradescantia'?'amber':''}"><span class="dot"></span>${demo?t(p.id==='tradescantia'?'check':'healthy'):latest?t('manual'):t(active?'waiting':'disconnected')}<span class="card-arrow">${icon('arrow',13)}</span></div></div></a>`;}
function chart(){if(state.mode!=='demo')return `<div class="real-empty"><div>${icon('drop',26)}<p>${t('sensorNone')}<br>${t('sensorNoneText')}</p>${button(t('measurement'),'log','plus','', 'data-type="measurement"')}</div></div>`;const colors=['#7a926d','#a39aa8'];const paths=state.channels.map((id,i)=>{const points=demoSeries(id,chartRange).map((n,j)=>`${34+j*18},${139-n*1.5}`);return `<path d="M${points.join(' L')}" fill="none" stroke="${colors[i]}" stroke-width="2.2"/><circle cx="466" cy="${139-demoSeries(id,chartRange).at(-1)*1.5}" r="3" fill="${colors[i]}"/>`;}).join('');return `<svg viewBox="0 0 490 172" class="chart" role="img" aria-label="${t('trendNote')}">${[20,40,60,80].map(n=>`<line x1="34" x2="469" y1="${139-n*1.5}" y2="${139-n*1.5}" stroke="#ecefe5" stroke-dasharray="3 5"/><text x="5" y="${143-n*1.5}">${n}</text>`).join('')}${paths}<text x="34" y="162">${chartRange==='day'?'00:00':t('weekAgo')}</text><text x="160" y="162">${chartRange==='day'?'08:00':''}</text><text x="300" y="162">${chartRange==='day'?'16:00':''}</text><text x="466" y="162" text-anchor="end">${t('now')}</text></svg><div class="chart-legend">${state.channels.map(id=>`<span><i></i>${t(id)}</span>`).join('')}</div>`;}
function checks(){try{const s=JSON.parse(localStorage.getItem(CHECK_KEY)||'{}');return s.day===new Date().toLocaleDateString('en-CA')?s.items:[];}catch{return [];}}
function overview(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">${t('workspace')}</div><h1>${t('headline')}</h1><p>${t('intro')}</p></div><div class="hero-art" aria-hidden="true">${plantArt('chlorophytum','hero')}<div class="hero-small">${plantArt('cactus','hero2')}</div></div></section><section class="stats" aria-label="${t('overview')}">${[['leaf','registered','03',t('species'),t('register')],['drop','channels','02','',t('configured')],['book','observations',String(events().length).padStart(2,'0'),'',t('local')]].map(([ico,label,value,unit,foot])=>`<div class="stat"><span class="stat-icon">${icon(ico,19)}</span><div class="stat-main"><div class="stat-label">${t(label)}</div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-foot">${foot}</div></div></div>`).join('')}</section><section><div class="section-top"><div><h2>${t('myPlants')}</h2><p>${t('plantsNote')}</p></div><a class="btn text" href="#plants">${t('viewAll')} ${icon('arrow',15)}</a></div><div class="plant-grid">${PLANTS.map(card).join('')}</div></section><div class="bottom-grid"><section class="panel"><div class="panel-top"><div><h2>${t('trend')}</h2><p class="panel-sub">${t(state.mode==='demo'?'trendNote':'manual')}</p></div><div class="segmented">${['day','week'].map(r=>`<button data-action="range" data-range="${r}" class="${r===chartRange?'active':''}" aria-pressed="${r===chartRange}">${t(r)}</button>`).join('')}</div></div>${chart()}</section><section class="panel care-panel"><h2>${t('care')}</h2><p class="panel-sub">${t('careNote')}</p>${['task1','task2','task3'].map((k,i)=>`<label class="care-item"><input type="checkbox" data-check="${i}" ${checks().includes(i)?'checked':''}><span>${t(k)}</span></label>`).join('')}${button(t('upload'),'photo','camera','')}<button class="check-reset" data-action="reset-checks">${t('checklistReset')}</button></section></div><div class="quote-banner">${icon('leaf',31)}<div><strong>${t('learn')}</strong><p>${t('learnText')}</p></div></div>`;}
function heading(title,intro){return `<div class="page-heading"><h1>${t(title)}</h1>${intro?`<p>${t(intro)}</p>`:''}</div>`;}
function plantView(id){const p=PLANTS.find(p=>p.id===id);if(!p)return plantsView();const ch=state.channels.indexOf(id);return `${heading('detail')}<a href="#plants" class="btn text">${icon('back',15)}${t('back')}</a><div class="detail-grid subsection"><div class="detail-art">${plantArt(id,'detail')}<h2 class="plant-name">${t(id)}</h2><div class="latin">${id==='cactus'?t('notSpecies'):p.latin}</div><p>${t('botanical')}<br>${t('modelLater')}</p></div><div class="panel"><div class="eyebrow">${t('careProfile')}</div><h2 style="margin-top:10px;font-size:29px">${t(id)}</h2><p class="panel-sub">${t(id+'Desc')}</p>${[['sensor',p.sensor],['channel',ch>=0?String(ch+1):t('reserve')],['calibration',t('notCalibrated')],['auto',t('unavailable')]].map(([k,v])=>`<div class="spec-row"><span>${t(k)}</span><strong>${v}</strong></div>`).join('')}<p class="wide-note">${t(id+'Care')}</p><p class="wide-note">${t('profileText')}</p><div class="button-row">${button(t('add'),'log','plus','primary',`data-plant="${id}"`)}${button(t('upload'),'photo','camera','',`data-plant="${id}"`)}</div></div></div><section class="panel subsection"><h2>${t('history')}</h2>${renderEvents(events().filter(e=>e.plantId===id))}</section>`;}
function plantsView(){return `${heading('myPlants','plantsNote')}<div class="plant-grid">${PLANTS.map(card).join('')}</div><section class="panel subsection"><h2>${t('connectedPlants')}</h2><p class="panel-sub">${t('connectionNote')}</p>${channelRows()}<p class="wide-note">${t('dataDisclaimer')}</p></section>`;}
function channelRows(){return state.channels.map((id,i)=>`<div class="channel-row"><span class="channel-name">${t('channel')} 0${i+1}</span><span class="channel-plant">${t(id)}</span>${button(t('swap'),'swap','chevrons','',`data-channel="${i}"`)}</div>`).join('');}
function renderEvents(list){if(!list.length)return `<div class="empty-state">${icon('book',30)}<h3>${t('emptyJournal')}</h3><p>${t('emptyJournalText')}</p>${button(t('add'),'log')}</div>`;return `<div class="event-list">${list.map(e=>`<article class="event-row"><div class="event-icon">${icon(e.type==='watering'?'drop':e.type==='photo'?'camera':'leaf',17)}</div><div class="event-content"><strong>${t(e.plantId)} · ${t(e.type)}</strong><span class="badge">${t(e.mode==='demo'?'demoLabel':'realLabel')}</span>${e.note?`<p>${esc(e.note)}</p>`:''}<p>${[['waterMl','ml'],['raw','ADC'],['moisture',t('unit')],['temperature','°C'],['humidity','% RH'],['lux','lx'],['weight','g']].filter(([k])=>e[k]!=null).map(([k,u])=>`${t(k==='moisture'?'moisture':k)}: ${esc(e[k])} ${u}`).join(' · ')}</p></div><time class="event-date" datetime="${e.date}">${date(e.date)}</time></article>`).join('')}</div>`;}
function journalView(){return `${heading('journal','dataScope')}<div class="toolbar"><label>${t('plant')} <select class="filter" id="journal-filter" style="width:auto;margin-left:10px"><option value="all">${t('all')}</option>${plantOptions(journalFilter)}</select></label>${button(t('exportCSV'),'csv','download','')}</div><section class="panel">${renderEvents(events().filter(e=>journalFilter==='all'||e.plantId===journalFilter))}</section>`;}
function photosView(){return `${heading('photoTitle','photoIntro')}<div class="toolbar">${button(t('upload'),'photo','camera')}<span class="privacy-note">${t('photoPrivacy')}</span></div><div class="notice">${icon('info',16)}<div><strong>${t('noAI')}</strong><br>${t('noAIText')}</div></div><div id="photo-list"><section class="panel"><div class="empty-state">${icon('camera',36)}<h3>${t('photoEmpty')}</h3><p>${t('photoEmptyText')}</p></div></section></div>`;}
function settingsView(){return `${heading('settings','dataTab')}<div class="settings-grid"><section class="panel"><h2>${t('mode')}</h2><p>${t('modeHelp')}</p>${['demo','real'].map(m=>`<label class="radio-row"><input type="radio" name="mode" value="${m}" ${state.mode===m?'checked':''}>${t(m)}</label>`).join('')}</section><section class="panel"><h2>${t('storage')}</h2><p>${t('storageText')}</p>${button(t('exportJSON'),'json','download','')}</section><section class="panel wide"><h2>${t('connectedPlants')}</h2><p>${t('connectionNote')}</p>${channelRows()}</section><section class="panel wide"><div class="panel-top"><h2>${t('notify')}</h2><span class="status-pill">${t('notConnected')}</span></div><p>${t('notifyText')}</p><form id="prefs-form"><div class="field-pair"><div class="field"><label for="email">${t('email')}</label><input id="email" name="email" type="email" autocomplete="email" maxlength="160" value="${esc(state.prefs?.email||'')}" placeholder="you@example.com"></div><div class="field"><label for="telegram">${t('telegram')}</label><input id="telegram" name="telegram" maxlength="40" value="${esc(state.prefs?.telegram||'')}" placeholder="@username" pattern="@?[A-Za-z0-9_]{5,32}"></div></div><button class="btn primary" type="submit">${t('savePrefs')}</button></form></section></div>`;}
function render(){const r=route();renderId++;photoURLs.forEach(URL.revokeObjectURL);photoURLs=[];document.documentElement.lang=state.lang;document.querySelector('.skip-link').textContent=state.lang==='ru'?'К содержимому':state.lang==='ro'?'La conținut':'Skip to content';app.innerHTML=shell(r.name==='overview'?overview():r.name==='plant'?plantView(r.id):r.name==='plants'?plantsView():r.name==='journal'?journalView():r.name==='photos'?photosView():settingsView());if(r.name==='photos')loadPhotos(renderId);document.title=`Folium · ${t(r.name==='plant'?'plants':r.name)}`;}
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${t(title)}</h2><button class="icon-button" data-action="close" aria-label="${t('cancel')}">${icon('close',17)}</button></div>${body}`;modal.showModal();}
function field(name,type='number',attrs=''){return `<div class="field"><label for="f-${name}">${t(name)}</label><input id="f-${name}" name="${name}" type="${type}" ${attrs}></div>`;}
function logModal(plantId='chlorophytum',type='observation'){openModal('logTitle',`<form id="log-form"><p class="hint">${t(state.mode==='demo'?'demoNote':'realNote')}</p><div class="field-pair"><div class="field"><label for="f-plant">${t('plant')}</label><select id="f-plant" name="plantId">${plantOptions(plantId)}</select></div><div class="field"><label for="f-type">${t('event')}</label><select id="f-type" name="type">${['observation','watering','feeding','repotting','moving','measurement'].map(k=>`<option value="${k}" ${type===k?'selected':''}>${t(k)}</option>`).join('')}</select></div></div><div class="field"><label for="f-note">${t('note')}</label><textarea id="f-note" name="note" maxlength="1000" placeholder="${t('notePlaceholder')}"></textarea></div><p class="hint">${t('optional')}</p><div class="input-grid">${field('waterMl','number','min="0" max="10000" step="0.1"')}${field('raw','number','min="0" max="65535" step="1"')}${field('moisture','number','min="0" max="100" step="0.1"')}${field('temperature','number','min="-20" max="60" step="0.1"')}${field('humidity','number','min="0" max="100" step="0.1"')}${field('lux','number','min="0" max="200000" step="1"')}${field('weight','number','min="0" max="100000" step="0.1"')}</div><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn" data-action="close">${t('cancel')}</button><button type="submit" class="btn primary">${t('save')}</button></div></form>`);}
function swapModal(channel){const options=PLANTS.filter(p=>!state.channels.includes(p.id));openModal('swapTitle',`<p class="modal-description">${t('swapText')}</p><form id="swap-form" data-channel="${channel}"><div class="field"><label for="new-plant">${t('newPlant')}</label><select name="plantId" id="new-plant">${options.map(p=>`<option value="${p.id}">${t(p.id)}</option>`).join('')}</select></div><label class="checkbox-label"><input type="checkbox" required><span>${t('swapAck')}</span></label><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn" data-action="close">${t('cancel')}</button><button type="submit" class="btn primary">${t('swapConfirm')}</button></div></form>`);}
function photoModal(plantId='chlorophytum'){openModal('photoTitle',`<form id="photo-form"><div class="field"><label for="photo-plant">${t('plant')}</label><select id="photo-plant" name="plantId">${plantOptions(plantId)}</select></div><div class="field"><label for="photo-file">${t('photoFile')}</label><input id="photo-file" name="file" type="file" accept="image/jpeg,image/png,image/webp" required><small>${t('photoHint')}</small></div><img class="photo-preview" id="photo-preview" alt="${t('photo')}"><div class="field"><label for="photo-note">${t('photoCaption')}</label><textarea name="note" id="photo-note" maxlength="1000"></textarea></div><div class="notice">${icon('info',15)}<span>${t('noAIText')}</span></div><p class="form-error" role="alert"></p><div class="modal-actions"><button class="btn" type="button" data-action="close">${t('cancel')}</button><button class="btn primary" type="submit">${t('save')}</button></div></form>`);}
const db=()=>new Promise((resolve,reject)=>{const req=indexedDB.open('folium-photos',1);req.onupgradeneeded=()=>req.result.createObjectStore('photos',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
async function dbOp(kind,value){const database=await db();try{return await new Promise((resolve,reject)=>{const tx=database.transaction('photos',kind==='getAll'?'readonly':'readwrite');const request=tx.objectStore('photos')[kind](...(value===undefined?[]:[value]));let result;request.onsuccess=()=>{result=request.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}finally{database.close();}}
async function loadPhotos(id){try{const list=(await dbOp('getAll')).filter(x=>x.mode===state.mode).sort((a,b)=>b.date.localeCompare(a.date));if(id!==renderId)return;const target=document.querySelector('#photo-list');if(!target||!list.length)return;target.className='photo-grid';target.innerHTML=list.map(p=>{const url=URL.createObjectURL(p.file);photoURLs.push(url);return `<article class="photo-card"><img src="${url}" alt="${t(p.plantId)} · ${date(p.date)}"><div class="photo-body"><h3>${t(p.plantId)}</h3><p>${date(p.date)} <span class="badge">${t(p.mode==='demo'?'demoLabel':'realLabel')}</span></p><p>${esc(p.note)}</p><div class="button-row"><a class="btn" href="${url}" download="${esc(p.file.name)}">${icon('download',14)}${t('download')}</a><button class="btn danger" data-action="delete-photo" data-id="${p.id}">${icon('trash',14)}${t('delete')}</button></div></div></article>`;}).join('');}catch{if(id===renderId)toast(t('error'));}}
async function validPhoto(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024||file.size===0)throw Error(t('photoError'));const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.width||!img.height)throw Error();}catch{throw Error(t('photoError'));}finally{URL.revokeObjectURL(url);}}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('exported'));}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='close')modal.close();if(action==='language'){if(persist({...state,lang:el.dataset.lang}))render();}if(action==='log')logModal(el.dataset.plant,el.dataset.type);if(action==='photo')photoModal(el.dataset.plant);if(action==='swap')swapModal(Number(el.dataset.channel));if(action==='range'){chartRange=el.dataset.range;render();}if(action==='csv')download(toCSV(events()),`folium-${state.mode}-observations.csv`,'text/csv;charset=utf-8');if(action==='json')download(JSON.stringify({app:'Folium',exportedAt:new Date().toISOString(),photoFilesIncluded:false,state},null,2),'folium-backup.json','application/json');if(action==='reset-checks'){try{localStorage.removeItem(CHECK_KEY);render();}catch{toast(t('error'));}}if(action==='delete-photo'){openModal('delete',`<p class="modal-description">${t('deletePhoto')}</p><form id="delete-photo-form" data-id="${el.dataset.id}"><p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" class="btn" data-action="close">${t('cancel')}</button><button type="submit" class="btn danger">${t('delete')}</button></div></form>`);} });
document.addEventListener('change',async e=>{if(e.target.matches('[data-check]')){try{const items=checks(),i=Number(e.target.dataset.check),next=e.target.checked?[...new Set([...items,i])]:items.filter(x=>x!==i);localStorage.setItem(CHECK_KEY,JSON.stringify({day:new Date().toLocaleDateString('en-CA'),items:next}));}catch{e.target.checked=!e.target.checked;toast(t('error'));}}if(e.target.id==='journal-filter'){journalFilter=e.target.value;render();}if(e.target.name==='mode'){if(persist({...state,mode:e.target.value}))render();}if(e.target.id==='photo-file'){const preview=document.querySelector('#photo-preview');if(preview.dataset.url)URL.revokeObjectURL(preview.dataset.url);preview.style.display='none';try{await validPhoto(e.target.files[0]);preview.src=URL.createObjectURL(e.target.files[0]);preview.dataset.url=preview.src;preview.style.display='block';modal.querySelector('.form-error').textContent='';}catch(error){modal.querySelector('.form-error').textContent=error.message;}}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['log-form','swap-form','photo-form','prefs-form','delete-photo-form'].includes(form.id))return;e.preventDefault();const data=new FormData(form);try{
 if(form.id==='delete-photo-form'){await dbOp('delete',form.dataset.id);modal.close();render();}
 if(form.id==='log-form'){const entry={plantId:data.get('plantId'),type:data.get('type'),note:data.get('note').trim()};for(const [k,min,max]of [['waterMl',0,10000],['raw',0,65535],['moisture',0,100],['temperature',-20,60],['humidity',0,100],['lux',0,200000],['weight',0,100000]])entry[k]=numeric(data.get(k),min,max);if(!entry.note&&!Object.entries(entry).some(([k,v])=>!['plantId','type','note'].includes(k)&&v!==null))throw Error(t('requiredNote'));if(persist(addEvent(state,entry))){modal.close();render();toast(t('saved'));}}
 if(form.id==='swap-form'){const channel=Number(form.dataset.channel),id=data.get('plantId');const result=replacePlant(state,channel,id);const next=addEvent(result.state,{plantId:id,type:'replacement',note:`${t('channel')} ${channel+1}: ${t(result.previous)} → ${t(id)}`});if(persist(next)){modal.close();render();toast(t('replaced'));}}
 if(form.id==='prefs-form'){if(persist({...state,prefs:{email:data.get('email').trim(),telegram:data.get('telegram').trim()}}))toast(t('prefsSaved'));}
 if(form.id==='photo-form'){const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const file=data.get('file');await validPhoto(file);await dbOp('put',{id:crypto.randomUUID(),plantId:data.get('plantId'),note:data.get('note').trim(),date:new Date().toISOString(),mode:state.mode,file});modal.close();location.hash='photos';render();toast(t('photoSaved'));}finally{submit.disabled=false;}}
 }catch(error){const err=form.querySelector('.form-error');if(err)err.textContent=error.message||t('error');else toast(t('error'));}});
modal.addEventListener('close',()=>{const p=modal.querySelector('#photo-preview');if(p?.dataset.url)URL.revokeObjectURL(p.dataset.url);});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));render();}catch{toast(t('error'));}}});
render();
